#include <stdlib.h>
#include <string.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ld(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void st(float *p, v8 v) { memcpy(p, &v, sizeof v); }
static inline v8 bc(float a) { v8 v = {a, a, a, a, a, a, a, a}; return v; }

static void kernel(const float *restrict Ap, const float *restrict Bp, int kc,
                   float *restrict C, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        const v8 *bp = (const v8 *)(Bp + k * NR);
        v8 b0 = bp[0], b1 = bp[1];
        const float *a = Ap + k * MR;
        v8 a0 = bc(a[0]); c00 += a0 * b0; c01 += a0 * b1;
        v8 a1 = bc(a[1]); c10 += a1 * b0; c11 += a1 * b1;
        v8 a2 = bc(a[2]); c20 += a2 * b0; c21 += a2 * b1;
        v8 a3 = bc(a[3]); c30 += a3 * b0; c31 += a3 * b1;
        v8 a4 = bc(a[4]); c40 += a4 * b0; c41 += a4 * b1;
        v8 a5 = bc(a[5]); c50 += a5 * b0; c51 += a5 * b1;
    }

    if (mr == MR && nr == NR) {
#define ROW(r, x0, x1) do { float *p = C + (r) * ldc; \
        if (first) { st(p, x0); st(p + 8, x1); } \
        else { st(p, ld(p) + x0); st(p + 8, ld(p + 8) + x1); } } while (0)
        ROW(0, c00, c01); ROW(1, c10, c11); ROW(2, c20, c21);
        ROW(3, c30, c31); ROW(4, c40, c41); ROW(5, c50, c51);
#undef ROW
    } else {
        float t[MR][NR];
        st(t[0], c00); st(t[0] + 8, c01);
        st(t[1], c10); st(t[1] + 8, c11);
        st(t[2], c20); st(t[2] + 8, c21);
        st(t[3], c30); st(t[3] + 8, c31);
        st(t[4], c40); st(t[4] + 8, c41);
        st(t[5], c50); st(t[5] + 8, c51);
        for (int r = 0; r < mr; r++) {
            float *p = C + r * ldc;
            if (first)
                for (int j = 0; j < nr; j++) p[j] = t[r][j];
            else
                for (int j = 0; j < nr; j++) p[j] += t[r][j];
        }
    }
}

static void *amalloc(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int np = (n + NR - 1) / NR;
    float *Bp = amalloc((size_t)np * NR * KC * sizeof(float));

    for (int kk = 0; kk < n; kk += KC) {
        int kc = n - kk < KC ? n - kk : KC;
        int first = (kk == 0);

        #pragma omp parallel
        {
            #pragma omp for schedule(static)
            for (int jp = 0; jp < np; jp++) {
                float *dst = Bp + (size_t)jp * NR * kc;
                int j0 = jp * NR;
                int jw = n - j0 < NR ? n - j0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(kk + k) * n + j0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < jw; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }

            float *Ap = amalloc((size_t)MC * KC * sizeof(float));

            #pragma omp for schedule(dynamic)
            for (int ib = 0; ib < n; ib += MC) {
                int mc = n - ib < MC ? n - ib : MC;
                int nt = (mc + MR - 1) / MR;

                for (int t = 0; t < nt; t++) {
                    float *dst = Ap + (size_t)t * MR * kc;
                    for (int r = 0; r < MR; r++) {
                        int row = ib + t * MR + r;
                        if (row < n) {
                            const float *src = A + (size_t)row * n + kk;
                            for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
                        }
                    }
                }

                for (int jp = 0; jp < np; jp++) {
                    int j0 = jp * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bp + (size_t)jp * NR * kc;
                    for (int t = 0; t < nt; t++) {
                        int i0 = ib + t * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        kernel(Ap + (size_t)t * MR * kc, bp, kc,
                               C + (size_t)i0 * n + j0, n, mr, nr, first);
                    }
                }
            }

            free(Ap);
        }
    }

    free(Bp);
}
